function applyPagePreview(doc,paper){const page=doc.sections[0]?.page;if(!page)return;const size=page.size||PAGE_SIZES.A4;const landscape=page.orientation==='landscape';const width=(landscape?size.height:size.width)/1440*96;const height=(landscape?size.width:size.height)/1440*96;paper.style.width=`${width}px`;paper.style.maxWidth='none';paper.style.minHeight=`${height}px`;paper.style.padding=`${(page.margins.top/1440*96)}px ${(page.margins.right/1440*96)}px ${(page.margins.bottom/1440*96)}px ${(page.margins.left/1440*96)}px`;paper.style.setProperty('--paper-padding-left',String(page.margins.left/1440*96)+'px');paper.style.setProperty('--paper-padding-top',String(page.margins.top/1440*96)+'px');const sizeName=Object.keys(PAGE_SIZES).find(k=>PAGE_SIZES[k].width===size.width&&PAGE_SIZES[k].height===size.height)||'A4';if(document.activeElement!==$('pageSize'))$('pageSize').value=sizeName;if(document.activeElement!==$('orientation'))$('orientation').value=page.orientation||'portrait';const marginName=Object.keys(PAGE_MARGINS).find(k=>PAGE_MARGINS[k].top===page.margins.top&&PAGE_MARGINS[k].right===page.margins.right&&PAGE_MARGINS[k].left===page.margins.left)||'normal';if(document.activeElement!==$('pageMargin'))$('pageMargin').value=marginName;}
function fitCanvasPage(){const canvas=$('paper')?.closest('.canvas');const paper=$('paper');if(!canvas||!paper)return;const pageWidth=Number.parseFloat(paper.style.width)||paper.getBoundingClientRect().width||794;const available=Math.max(240,canvas.clientWidth-32);const scale=Math.min(1,available/pageWidth);paper.style.zoom=String(Math.round(scale*1000)/1000);canvas.style.setProperty('--page-scale',String(scale));}const canvasResizeObserver=new ResizeObserver(()=>fitCanvasPage());canvasResizeObserver.observe(document.querySelector('.canvas'));function updatePageSetup(){const doc=JSON.parse(JSON.stringify(editor.state.document));const size=PAGE_SIZES[$('pageSize').value]||PAGE_SIZES.A4;const orientation=$('orientation').value;const margins=PAGE_MARGINS[$('pageMargin').value]||PAGE_MARGINS.normal;for(const section of doc.sections){section.page={...section.page,size:{...size},orientation,margins:{...margins}}}if(replaceModel(doc))$('status').textContent=`Page setup applied: ${$('pageSize').value}, ${orientation}, ${$('pageMargin').value} margins`;}
