function queueSessionSave(){if(!sessionRestored)return;clearTimeout(sessionSaveTimer);sessionSaveTimer=setTimeout(persistPreviewSession,650);}
async function persistPreviewSession(){if(!sessionRestored)return;if(sessionSaveBusy){sessionSaveAgain=true;return}sessionSaveBusy=true;try{const ui={currentView,scrollTop:document.querySelector('.canvas')?.scrollTop||0,fieldValues:fieldValuesObject()};const savedAt=await savePreviewSession(editor.state.document,ui);try{localStorage.removeItem('convetlib-preview-emergency')}catch{}const stamp=new Date(savedAt);$('sessionStatus').textContent='Tersimpan otomatis · '+stamp.toLocaleTimeString('id-ID',{hour:'2-digit',minute:'2-digit'});$('sessionStatus').title='Sesi desain tersimpan di browser ini pada '+stamp.toLocaleString('id-ID');}catch(error){$('sessionStatus').textContent='Gagal menyimpan sesi';$('sessionStatus').title=error?.message||String(error)}finally{sessionSaveBusy=false;if(sessionSaveAgain){sessionSaveAgain=false;queueSessionSave()}}}
