function renderHeaderFooterVariants(doc){if(currentView!=='preview')return;const variants=[{key:'firstPageHeader',label:'Header halaman pertama',host:'.letterhead'},{key:'evenPageHeader',label:'Header halaman genap',host:'.letterhead'},{key:'firstPageFooter',label:'Footer halaman pertama',host:'.letterfoot'},{key:'evenPageFooter',label:'Footer halaman genap',host:'.letterfoot'}];for(let sectionIndex=0;sectionIndex<doc.sections.length;sectionIndex++){const section=doc.sections[sectionIndex];if(section.kind==='canvas')continue;for(const variant of variants){const host=$('paper').querySelectorAll('.letterhead, .letterfoot');const base=Array.from(host).find(el=>Number(el.closest('[data-section-index]')?.dataset.sectionIndex??sectionIndex)===sectionIndex&&el.matches(variant.host));if(!base)continue;const panel=document.createElement('div');panel.className='variant-region';panel.dataset.sectionIndex=String(sectionIndex);panel.dataset.region=variant.key;panel.innerHTML=`<div class="drag-region-label">${variant.label} · seret blok antar area</div><div class="document-block-list variant-block-list" data-section-index="${sectionIndex}" data-region="${variant.key}">${(section[variant.key]||[]).map((block,blockIndex)=>`<div class="doc-block variant-doc-block" data-block-id="${esc(block.id||'')}" data-block-index="${blockIndex}" draggable="${block.id?'true':'false'}">${blockHtml(block)}<button type="button" class="variant-remove" data-remove-variant="${variant.key}" data-section-index="${sectionIndex}" data-block-index="${blockIndex}">Hapus blok</button></div>`).join('')}</div><button type="button" class="variant-add" data-add-variant="${variant.key}" data-section-index="${sectionIndex}">+ Tambah blok</button>`;base.append(panel);}}}
$('paper').addEventListener('click',event=>{const remove=event.target.closest('[data-remove-variant]');const add=event.target.closest('[data-add-variant]');if(!remove&&!add)return;const button=remove||add,sectionIndex=Number(button.dataset.sectionIndex),slot=remove?remove.dataset.removeVariant:add.dataset.addVariant;const doc=JSON.parse(JSON.stringify(editor.state.document));const section=doc.sections[sectionIndex];if(!section||!['firstPageHeader','firstPageFooter','evenPageHeader','evenPageFooter'].includes(slot))return;if(remove){const index=Number(remove.dataset.blockIndex);if(!Array.isArray(section[slot])||!section[slot][index])return;section[slot].splice(index,1);if(!section[slot].length)section[slot]=[];if(replaceModel(doc))$('status').textContent=`Blok dihapus dari ${slot}`;return;}section[slot]=section[slot]||[];section[slot].push(p(''));if(replaceModel(doc))$('status').textContent=`Blok ditambahkan ke ${slot}`;});
function countNodes(nodes){let count=0;for(const node of nodes||[]){count++;if(node.content)count+=countNodes(node.content.filter(x=>x.id));}return count;}
function flatText(sections){const out=[];const walk=nodes=>{for(const x of nodes||[]){if(x.type==='text')out.push(x.text);else if(x.id){if(x.type==='table')out.push('\n[TABLE]\n');walk(x.content);out.push('\n')}else if(x.type==='placeholder')out.push(`{{${x.attrs?.key||'unknown'}}}`)}};for(const s of sections)walk(s.content);return out.join('').replace(/\n{3,}/g,'\n\n');}
