function normalizeDocumentPlaceholders(doc){let converted=0;const inlinePattern=/\{\{\s*([A-Za-z][A-Za-z0-9_-]*(?:\.[A-Za-z0-9_-]+)*)\s*\}\}/g;const walk=nodes=>{if(!Array.isArray(nodes))return;for(let i=0;i<nodes.length;){const node=nodes[i];if(node?.type==='text'&&typeof node.text==='string'){let end=i;while(end<nodes.length&&nodes[end]?.type==='text'&&typeof nodes[end].text==='string')end++;const group=nodes.slice(i,end);const full=group.map(x=>x.text).join('');const matches=[...full.matchAll(inlinePattern)];if(matches.length){const segments=[];let offset=0;for(const item of group){segments.push({start:offset,end:offset+item.text.length,node:item});offset+=item.text.length;}const replacement=[];let cursor=0;const addTextRange=(from,to)=>{for(const seg of segments){const a=Math.max(from,seg.start),b=Math.min(to,seg.end);if(a<b)replacement.push({...seg.node,text:full.slice(a,b)});}};for(const match of matches){const start=match.index,endMatch=start+match[0].length;if(start>cursor)addTextRange(cursor,start);replacement.push({type:'placeholder',attrs:{key:match[1]}});converted++;cursor=endMatch;}if(cursor<full.length)addTextRange(cursor,full.length);nodes.splice(i,group.length,...replacement);i+=replacement.length;continue;}i=end;continue;}if(node?.id&&Array.isArray(node.content))walk(node.content);i++;}};for(const section of doc.sections||[]){for(const region of ['header','content','footer','firstPageHeader','firstPageFooter','evenPageHeader','evenPageFooter'])walk(section[region]);}return converted;}
