function replaceFieldKey(doc,oldKey,newKey){visitNodes(doc.sections, node=>{if(node.type==='placeholder'&&node.attrs?.key===oldKey)node.attrs.key=newKey;if(node.type==='text'&&typeof node.text==='string')node.text=node.text.replaceAll(`{{${oldKey}}}`,`{{${newKey}}}`)});}
function removeFieldKey(doc,key){const clean=nodes=>(nodes||[]).filter(node=>{if(node.type==='placeholder'&&node.attrs?.key===key)return false;if(node.type==='text'&&typeof node.text==='string')node.text=node.text.replaceAll(`{{${key}}}`,'');if(node.id&&node.content)node.content=clean(node.content);return true});for(const section of doc.sections){section.header=clean(section.header);section.content=clean(section.content);section.footer=clean(section.footer);section.firstPageHeader=clean(section.firstPageHeader);section.firstPageFooter=clean(section.firstPageFooter);section.evenPageHeader=clean(section.evenPageHeader);section.evenPageFooter=clean(section.evenPageFooter)}}
function fieldAction(label,action){const button=document.createElement('button');button.type='button';button.className='field-action';button.textContent=label;button.setAttribute('aria-label',label);button.onclick=action;return button;}
