$('json').addEventListener('change',()=>{try{const raw=JSON.parse($('json').value);const normalized=normalizeImportedStructure(raw);const value=normalized.document;const filled=ensureSectionContent(value);if(!replaceModel(value))$('status').textContent='JSON ditolak: schema validation gagal';else{const f=normalized.fixes;const repaired=f.headingLevels+f.lists+f.emptyTables+f.comments+f.revisions+f.unknownNodes+f.flatText;if(repaired)$('status').textContent=`JSON diperbaiki otomatis: ${f.headingLevels} heading, ${f.lists} list, ${f.emptyTables} tabel kosong, ${f.comments} komentar, ${f.revisions} revision, ${f.unknownNodes} node tidak dikenal, ${f.flatText} blok teks flat.`;else if(filled)$('status').textContent='Konten dikosongkan: paragraf kosong dipertahankan agar section tetap valid; teks lama dihapus dari preview.';$('json').value=JSON.stringify(value,null,2)}}catch(e){$('status').textContent=`JSON parse error: ${e.message}`}});
