async function importDocumentFile(file){if(!file)return;const ext=file.name.split('.').pop()?.toLowerCase();$('status').textContent=`Reading ${file.name}…`;try{if(file.size>25*1024*1024)throw new Error('File exceeds 25 MiB import limit');if(ext==='json'){let value=JSON.parse(await file.text());lastExternalImport=null;const jsonFormat=detectJSONFormat(value);if(jsonFormat==='native'){/* native Convetlib JSON: original import path, unchanged */}else{if(jsonFormat==='external'){value=prepareExternalDocumentJSON(value);}else{throw new Error('Format JSON tidak dikenali: harus berupa dokumen Convetlib atau JSON eksternal dengan array sections yang berisi content');}}value=mergeImportIntoActiveCanvas(value)||preserveBlankCanvases(editor.state.document,value,ids);if(lastExternalImport?.custom){const prev=value.meta?.custom||{};value.meta={...value.meta,custom:{...prev,externalImports:{...(prev.externalImports||{}),[lastExternalImport.sourceId||'external']:lastExternalImport.custom}}};}const normalized=normalizeImportedStructure(value);value=normalized.document;const detected=normalizeDocumentPlaceholders(value);if(replaceModel(value)){const f=normalized.fixes;const repaired=f.headingLevels+f.lists+f.emptyTables+f.comments+f.revisions+f.unknownNodes+f.flatText;const repairNote=repaired?' · repaired '+f.headingLevels+' heading(s), '+f.lists+' list(s), '+f.emptyTables+' empty table(s), '+f.comments+' comment(s), '+f.revisions+' revision(s), '+f.unknownNodes+' unknown node(s), '+f.flatText+' flat text(s)':'';$('status').textContent='Loaded '+file.name+' into core model · '+collectFields(value.sections).size+' placeholder(s) detected'+(detected?' · '+detected+' converted to field token(s)':'')+repairNote;if(lastExternalImport){const r=lastExternalImport.report;$('status').textContent+=' · JSON eksternal dikonversi: '+r.sections+' section(s), '+Object.entries(r.blocks).map(([k,v])=>v+' '+k).join(', ')+(r.comments?', '+r.comments+' komentar':'')+(r.revisionsPreserved?', '+r.revisionsPreserved+' revisi disimpan di meta.custom':'')+(r.unknownNodes?', '+r.unknownNodes+' node tidak dikenal dijaga sebagai paragraf':'');}}else throw new Error('JSON import failed core schema validation');return}if(ext!=='docx'&&ext!=='dotx')throw new Error('Unsupported file. Choose .docx, .dotx, or .json');const bytes=new Uint8Array(await file.arrayBuffer());if(bytes.length<4||bytes[0]!==0x50||bytes[1]!==0x4b)throw new Error('File is not a valid OOXML ZIP package');const {importDocx}=await import('@convetlib/docx');let doc=await importDocx(bytes,{title:file.name.replace(/\.(docx|dotx)$/i,'')});doc=mergeImportIntoActiveCanvas(doc)||preserveBlankCanvases(editor.state.document,doc,ids);const detected=normalizeDocumentPlaceholders(doc);const detectedKeys=collectFields((doc.sections||[]).flatMap(s=>[...(s.header||[]),...(s.content||[]),...(s.footer||[]),...(s.firstPageHeader||[]),...(s.firstPageFooter||[]),...(s.evenPageHeader||[]),...(s.evenPageFooter||[])]));if(!replaceModel(doc))throw new Error('Imported document failed core schema validation');const sections=doc.sections||[];const nodes=allNodes(sections.flatMap(s=>[...(s.header||[]),...(s.content||[]),...(s.footer||[])]));const count=type=>nodes.filter(node=>node.type===type).length;const textLength=nodes.reduce((n,node)=>n+(node.type==='text'&&typeof node.text==='string'?node.text.length:0),0);$('status').textContent=`Imported ${file.name} · ${sections.length} section(s) · ${count('paragraph')} paragraph(s) · ${count('table')} table(s) · ${count('image')} image(s) · ${detectedKeys.size} placeholder(s) detected${detected?` · ${detected} converted to field token(s)`:''} · ${textLength} text characters`;const title=$('docTitle');if(title)title.value=doc.meta?.title||file.name.replace(/\.(docx|dotx)$/i,'');}catch(err){$('status').textContent=`Import failed: ${err instanceof Error?err.message:String(err)}`;throw err}}
