// Alt+drag: move the selected image between blocks (before/after another block, also across sections) as a model transaction.
function startImageReorder(event,block){const id=block.dataset.blockId;const paper=$('paper');let target=null,placement='after',moved=false;const clear=()=>paper.querySelectorAll('.drop-before,.drop-after').forEach(el=>el.classList.remove('drop-before','drop-after'));
const find=e=>{const hit=document.elementsFromPoint(e.clientX,e.clientY).map(el=>el.closest?.('.doc-block')).find(el=>el&&el.dataset.blockId&&el.dataset.blockId!==id&&paper.contains(el));clear();target=hit||null;if(!target)return;const r=target.getBoundingClientRect();placement=e.clientY<r.top+r.height/2?'before':'after';target.classList.add(placement==='before'?'drop-before':'drop-after')};
const move=e=>{if(Math.hypot(e.clientX-event.clientX,e.clientY-event.clientY)>3)moved=true;if(!moved)return;find(e);$('status').textContent=target?`Lepas untuk menaruh gambar ${placement==='before'?'sebelum':'sesudah'} blok`:'Seret ke blok lain (Alt+seret). Esc untuk batal'};
const stop=()=>{window.removeEventListener('pointermove',move,true);window.removeEventListener('pointerup',up,true);window.removeEventListener('keydown',key,true);clear()};
const up=e=>{find(e);const t=target,p=placement;stop();if(!moved||!t)return;const result=editor.commands.execute('image.moveTo',{imageId:id,targetId:t.dataset.blockId,placement:p});if(!result.ok){$('status').textContent='Gagal memindahkan gambar: '+result.reason;return}render();const again=[...paper.querySelectorAll('.doc-block.image-block')].find(el=>el.dataset.blockId===id);selectedImage={id,sectionIndex:Number(again?.closest('[data-section-index]')?.dataset.sectionIndex)};applyImageSelection();$('status').textContent='Gambar dipindahkan ke posisi baru'};
const key=e=>{if(e.key==='Escape'){stop();$('status').textContent='Pemindahan gambar dibatalkan'}};
window.addEventListener('pointermove',move,true);window.addEventListener('pointerup',up,true);window.addEventListener('keydown',key,true)}
function runEditorCommand(command,args){browserBinding.refreshSelection();const result=editor.commands.execute(command,args);if(!result.ok)$('status').textContent=`${command}: ${result.reason||'command unavailable'}`;else $('status').textContent=`Applied ${command}`;}
for(const id of ['bold','italic','underline','alignleft','aligncenter','alignright'])$(id).addEventListener('mousedown',e=>e.preventDefault());
$('bold').onclick=()=>runEditorCommand('text.toggleBold');$('italic').onclick=()=>runEditorCommand('text.toggleItalic');$('underline').onclick=()=>runEditorCommand('text.toggleUnderline');
let savedTextColorSelection=null;
function captureTextColorSelection(){browserBinding.refreshSelection();const selection=editor.state.selection;if(selection&& (selection.anchor.blockId!==selection.head.blockId||selection.anchor.offset!==selection.head.offset)){savedTextColorSelection={anchor:{...selection.anchor},head:{...selection.head}};return true}savedTextColorSelection=null;return false}
function restoreTextColorSelection(){if(savedTextColorSelection)setSelection(editor,savedTextColorSelection)}
function applyTextColor(value){const color=String(value||'').trim();if(!/^#[0-9a-f]{6}$/i.test(color)){$('status').textContent='Kode warna harus HEX 6 digit, contoh #1A2B3C';return}restoreTextColorSelection();$('textColor').value=color;$('textColorHex').value=color.toUpperCase();runEditorCommand('text.setColor',{color});}
$('textColor').addEventListener('pointerdown',captureTextColorSelection);
