$('alignleft').onclick=()=>runEditorCommand('block.setAlignment',{align:'left'});$('aligncenter').onclick=()=>runEditorCommand('block.setAlignment',{align:'center'});$('alignright').onclick=()=>runEditorCommand('block.setAlignment',{align:'right'});

