async function restorePreviewSession(){
  let record=null;
  try{record=await loadPreviewSession()}catch(error){$('sessionStatus').textContent='Database sesi tidak tersedia';$('sessionStatus').title=error?.message||String(error)}
  try{const emergencyText=localStorage.getItem('convetlib-preview-emergency');if(emergencyText){const emergency=JSON.parse(emergencyText);if(!record||new Date(emergency.savedAt||0)>new Date(record.savedAt||0))record=emergency}}catch{}
  if(record?.document){const parsed=parseDocument(record.document);if(parsed.ok){const restored=editor.replaceDocument(parsed.document);if(restored.ok){if(['preview','html','text','json'].includes(record.ui?.currentView))currentView=record.ui.currentView;restoreFieldValues(record.ui?.fieldValues);sessionRestored=true;$('sessionStatus').textContent='Sesi dipulihkan';$('sessionStatus').title='Desain terakhir dipulihkan dari penyimpanan browser: '+new Date(record.savedAt||Date.now()).toLocaleString('id-ID');}else{$('sessionStatus').textContent='Sesi gagal dipulihkan';}}else{$('sessionStatus').textContent='Sesi lama perlu diperiksa';$('sessionStatus').title=parsed.issues?.map(x=>x.message).join('; ')||'Dokumen tersimpan tidak valid';}}
  else{$('sessionStatus').textContent='Sesi baru · autosave aktif';sessionRestored=true;}
  render();
  if(record?.ui?.scrollTop)requestAnimationFrame(()=>{const canvas=document.querySelector('.canvas');if(canvas)canvas.scrollTop=record.ui.scrollTop});
  queueSessionSave();
}
